package net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.SmtpOutboundConfig;
import net.civeira.phylax.feature.notification.smtpoutboundconfig.domain.valueobject.MaxRetriesVO;

class MaxRetriesValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of max retries of smtp outbound config")
  void test_max_retries_value_holder_assign_plain_value() {
    Object holder = new Object();
    MaxRetriesValueHolder<Object> value = new MaxRetriesValueHolder<>(holder);
    Assertions.assertSame(holder, value.maxRetries(1), "Setters must return the holder");
    Assertions.assertTrue(value.getMaxRetriesValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(1, value.getMaxRetries().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of max retries of smtp outbound config")
  void test_max_retries_value_holder_assign_value_object() {
    Object holder = new Object();
    MaxRetriesValueHolder<Object> value = new MaxRetriesValueHolder<>(holder);
    MaxRetriesVO vo = MaxRetriesVO.from(1);
    Assertions.assertFalse(value.getMaxRetriesValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.maxRetries(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getMaxRetriesValue().orElseThrow());
    Assertions.assertSame(holder, value.maxRetries(Optional.empty()));
    Assertions.assertFalse(value.getMaxRetriesValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.maxRetries(Optional.of(vo)));
    Assertions.assertSame(vo, value.getMaxRetriesValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of max retries of smtp outbound config against the original")
  void test_max_retries_value_holder_read() {
    Object holder = new Object();
    MaxRetriesValueHolder<Object> value = new MaxRetriesValueHolder<>(holder);
    MaxRetriesVO vo = MaxRetriesVO.from(1);
    MaxRetriesVO other = MaxRetriesVO.from(1);
    SmtpOutboundConfig original = Mockito.mock(SmtpOutboundConfig.class);
    Mockito.when(original.getMaxRetriesValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readMaxRetries(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readMaxRetries(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.maxRetries(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readMaxRetries(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readMaxRetries(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of max retries of smtp outbound config")
  void test_max_retries_value_holder_unset() {
    Object holder = new Object();
    MaxRetriesValueHolder<Object> value = new MaxRetriesValueHolder<>(holder);
    MaxRetriesVO vo = MaxRetriesVO.from(1);
    value.maxRetries(vo);
    Assertions.assertSame(holder, value.unsetMaxRetriesIfMatches("maxRetries_other"));
    Assertions.assertTrue(value.getMaxRetriesValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetMaxRetriesIfMatches("maxRetries"));
    Assertions.assertFalse(value.getMaxRetriesValue().isPresent(),
        "The field name must clear the value");
    value.maxRetries(vo);
    Assertions.assertSame(holder, value.unsetMaxRetries());
    Assertions.assertFalse(value.getMaxRetriesValue().isPresent(), "Unset must clear the value");
  }
}
